import subprocess, re
def run(args, inp):
    p=subprocess.run(["./executable"]+args, input=inp+"\n", capture_output=True, text=True, timeout=5)
    return p.stdout
def iso(g, s):
    return repr(run(["--disable-builtin-keywords","--enable",g], s))
def stripped(s):
    return re.sub(r'\x1b\[[0-9;]*m', '', s)

