for s in ["0x1234567890123456","0xFFFFFFFFFFFFFFFF"]:
    out=run(["--disable-builtin-keywords","--enable","pointers"], s)
    print(f"IN {s!r} OUT {repr(out)} STRIPPED {repr(stripped(out))}")

print("=== json stripped ===")
for s in ["1e10","1.50","  {\"a\": 1}  "]:
    out=run(["--disable-builtin-keywords","--enable","json"], s)
    print(f"IN {s!r} OUT {repr(out)} STRIPPED {repr(stripped(out))}")
PY"}

