fn uuid_simple() -> String {
    // generate simple uuid-like random? Use tempfile + process id + time?
    use std::time::{SystemTime, UNIX_EPOCH};
    let t = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
