fn print_file_follow(path: &Path, highlighter: &Highlighter) -> Result<(), AppError> {
    use std::io::{BufReader, Seek, SeekFrom};
    let mut stdout = io::stdout();
    // print initial
    let content = fs::read_to_string(path).map_err(|_| AppError{code:1})?;
    for line in content.lines() {
        writeln!(stdout, "{}", highlighter.highlight(line)).unwrap();
    }
    stdout.flush().unwrap();
    // follow: poll file for new content
    let mut pos = fs::metadata(path).map(|m| m.len()).unwrap_or(0);
    loop {
        std::thread::sleep(std::time::Duration::from_millis(200));
        let md = match fs::metadata(path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        let len = md.len();
        if len < pos {
            pos = 0; // truncated
        }
        if len > pos {
            let mut f = fs::File::open(path).unwrap();
            f.seek(SeekFrom::Start(pos)).unwrap();
            let mut reader = BufReader::new(f);
            let mut buf = String::new();
            // read new bytes
            use std::io::Read;
            let mut new_data = Vec::new();
            reader.read_to_end(&mut new_data).unwrap();
            let s = String::from_utf8_lossy(&new_data);
            for line in s.lines() {
                // handle partial lines? Simplify: assume lines end with \n, print each
                writeln!(stdout, "{}", highlighter.highlight(line)).unwrap();
            }
            // if s doesn't end with \n, last line may be partial - but for simplicity print as is
            stdout.flush().unwrap();
            pos = len;
        }
    }
}

