struct AppError { code: i32 }

fn run(matches: clap::ArgMatches) -> Result<(), AppError> {
    // validate highlight
    let highlights: Vec<String> = matches.get_many::<String>("highlight").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut parsed_highlights: Vec<(String, Vec<String>)> = Vec::new();
    for h in &highlights {
        if let Some(idx) = h.find(':') {
            let color = &h[..idx];
            let words_str = &h[idx+1..];
            let color_lower = color.to_lowercase();
            if !["red","green","yellow","blue","magenta","cyan"].contains(&color_lower.as_str()) {
                eprintln!("error: invalid value '{}' for '--highlight <COLOR_WORD>': invalid variant: {}", h, color);
                eprintln!("\nFor more information, try '--help'.");
                return Err(AppError{code:2});
            }
            // words split by ',' - keep as is (including empty? will handle later)
            let words: Vec<String> = words_str.split(',').map(|s| s.to_string()).collect();
            parsed_highlights.push((color_lower, words));
        } else {
            eprintln!("error: invalid value '{}' for '--highlight <COLOR_WORD>': Expected format COLOR:word1,word2,... found `{}`", h, h);
            eprintln!("\nFor more information, try '--help'.");
            return Err(AppError{code:2});
        }
    }
    // check enable+disable
    let enable: Vec<String> = matches.get_many::<String>("enable").map(|v| v.cloned().collect()).unwrap_or_default();
    let disable: Vec<String> = matches.get_many::<String>("disable").map(|v| v.cloned().collect()).unwrap_or_default();
    if !enable.is_empty() && !disable.is_empty() {
        eprintln!("Error:   × cannot both enable and disable highlighters\n");
        return Err(AppError{code:1});
    }
    // config path
    let config_path_opt: Option<String> = matches.get_one::<String>("config-path").cloned();
    // pager
    let pager_flag: Option<String> = matches.get_one::<String>("pager").cloned();
    let pager_env: Option<String> = std::env::var("TAILSPIN_PAGER").ok().filter(|s| !s.is_empty());
    // Note: clap env disabled, so manually check env. Flag takes precedence.
    let pager_opt: Option<String> = pager_flag.or(pager_env);
    // validate pager if present? Only when pager will be used? Original validates pager even when piped? For file with pipe and pager flag, it validates. For stdin? Let's validate if pager_opt present and will be used?
    // Actually original validates pager when file is given? For stdin with pager? Probably not used. Let's validate only when pager will be used (file without -p and TTY? or file with explicit pager and pipe?).
    // Simplify: validate pager if present and (file.is_some() || exec.is_some())? For now validate if pager_opt present.
    // But need to handle that pager validation error is exit 1 with "Could not parse custom pager command" when pager has <2 tokens?
    // We'll validate later when pager is actually used.

    // theme loading
    let theme = load_theme(config_path_opt.as_deref())?;

    // build highlighter
    let disable_builtin = matches.get_flag("disable-builtin-keywords");
    let highlighter = Highlighter::new(&theme, &enable, &disable, disable_builtin, parsed_highlights);

    let file_opt: Option<String> = matches.get_one::<String>("FILE").cloned();
    let follow = matches.get_flag("follow");
    let print_flag = matches.get_flag("print");
    let exec_opt: Option<String> = matches.get_one::<String>("exec").cloned();

    // handle exec
    if let Some(cmd) = exec_opt {
        return handle_exec(&cmd, &highlighter, pager_opt.as_deref(), follow, print_flag);
    }

    // handle file vs stdin
    if let Some(fpath) = file_opt {
        return handle_file(&fpath, &highlighter, pager_opt.as_deref(), follow, print_flag);
    } else {
        // stdin
        // check if stdin is tty and no data? If stdin is tty (interactive) with no pipe, what to do? Original with no args and no stdin (tty) would wait? Let's just read stdin.
        // If follow flag with stdin? Follow stdin? Probably just print and follow? For now, handle stdin as print (always).
        // pager not used for stdin (always print).
        return handle_stdin(&highlighter, follow);
