fn handle_stdin(highlighter: &Highlighter, _follow: bool) -> Result<(), AppError> {
    let stdin = io::stdin();
    let mut stdout = io::stdout();
    // check if stdin is terminal? If stdin is tty and no data, we should not block forever? Original with no args and tty stdin would wait for input? Let's just read lines.
    // Use is_terminal to detect? If stdin is tty, maybe exit? But original with no args and empty stdin (closed) gave empty output exit 0. Good. So just read.
