fn parse_pager(cmd: &str) -> Result<(String, Vec<String>), ()> {
    let trimmed = cmd.trim();
    if trimmed.is_empty() {
        return Err(());
    }
    // split by whitespace (handle multiple spaces)
    let parts: Vec<String> = trimmed.split_whitespace().map(|s| s.to_string()).collect();
    if parts.len() < 2 {
        return Err(());
    }
    // check for [FILE]? Actually "cat FILE" (without brackets) was considered valid (2 parts, no [FILE]), so [FILE] not required.
    // What about "[FILE]" alone (1 part) -> invalid (already <2). Good.
    // What about "cat" alone (1 part) -> invalid. Good.
    // So only check len>=2? What about "  cat [FILE]  " (with spaces) -> trimmed split gives 2 parts, valid. Good.
    Ok((parts[0].clone(), parts[1..].to_vec()))
}

