    // For now, implement as: split cmd_str by whitespace (respecting quotes? Probably simple split?), first is bin, rest args, run, capture output, highlight, page.
    // If stdout is tty, use pager (default less or custom).
    let pager_cmd = pager_opt.unwrap_or("less -R [FILE]");
    if let Err(_) = parse_pager(pager_cmd) {
        eprintln!("Error:   × Could not parse custom pager command\n");
        return Err(AppError{code:1});
    }
    // split cmd_str
    let parts: Vec<String> = cmd_str.split_whitespace().map(|s| s.to_string()).collect();
    if parts.is_empty() {
        return Ok(());
    }
    let bin = &parts[0];
    let args = &parts[1..];
    // run command, capture output
    let output = match process::Command::new(bin).args(args).output() {
        Ok(o) => o,
        Err(e) => {
            // what error for exec command not found? Probably similar to pager? Let's just return?
            eprintln!("Error: failed to run command: {}\n", e);
            return Err(AppError{code:1});
        }
    };
    let stdout_str = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<String> = stdout_str.lines().map(|l| highlighter.highlight(l)).collect();
    run_pager(pager_cmd, &lines, false, Path::new("/tmp"))?;
    Ok(())
}

