pub struct AppError { pub code: i32 }

pub fn load_theme(config_path_opt: Option<&str>) -> Result<Theme, AppError> {
    let mut theme = Theme::default_theme();
    let path_opt: Option<String> = if let Some(p) = config_path_opt {
        Some(p.to_string())
    } else {
        // default path
        if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
            if !xdg.is_empty() {
                Some(format!("{}/tailspin/theme.toml", xdg))
            } else {
                dirs_fallback()
            }
        } else {
            dirs_fallback()
        }
    };
    fn dirs_fallback() -> Option<String> {
        if let Ok(home) = std::env::var("HOME") {
            Some(format!("{}/.config/tailspin/theme.toml", home))
        } else {
            None
        }
    }
    let path_str = match path_opt {
        Some(s) => s,
        None => return Ok(theme),
    };
    // check existence for default vs explicit?
    let is_explicit = config_path_opt.is_some();
    match std::fs::read_to_string(&path_str) {
        Ok(content) => {
            if content.trim().is_empty() {
                return Ok(theme);
            }
            match toml::from_str::<ThemeFile>(&content) {
                Ok(file) => {
                    theme.apply_file(file);
                    Ok(theme)
                }
                Err(e) => {
                    print_toml_error(&e);
                    Err(AppError{code:1})
                }
            }
        }
        Err(e) => {
            use std::io::ErrorKind;
            if e.kind() == ErrorKind::NotFound {
                if is_explicit {
                    eprintln!("Error:   × could not find the TOML file\n");
                    Err(AppError{code:1})
                } else {
                    Ok(theme)
                }
            } else {
                // other io error (e.g., IsADirectory)
                let msg = e.to_string();
                // e.to_string for IsADirectory is "Is a directory (os error 21)"
                eprintln!("Error:   × could not read the TOML file: {}\n  ╰─▶ {}\n", msg, msg);
                Err(AppError{code:1})
            }
        }
    }
}

fn print_toml_error(e: &toml::de::Error) {
    let s = e.to_string();
    // s is like "TOML parse error at line 1, column 9\n  |\n1 | ...\n  | ...\nmessage..."
    let mut lines = s.lines();
    let first = lines.next().unwrap_or("");
    eprintln!("Error:   × {}", first);
    for line in lines {
        // each remaining line in s starts with "  |" or "1 |" or message
        // prefix with "  │ "
        // But need to handle that s lines already have leading spaces? For "  |", prefix gives "  │   |" as desired.
        // For "1 | ...", prefix gives "  │ 1 | ..."
        // For message, prefix gives "  │ message"
        eprintln!("  │ {}", line);
    }
    eprintln!("  │ ");
    eprintln!();
}
