#[derive(Deserialize, Clone, Debug, Default)]
pub struct Style {
    #[serde(default)]
    pub fg: Option<Color>,
    #[serde(default)]
    pub bg: Option<Color>,
    #[serde(default)]
    pub bold: Option<bool>,
    #[serde(default)]
    pub faint: Option<bool>,
    #[serde(default)]
    pub italic: Option<bool>,
    #[serde(default)]
    pub underline: Option<bool>,
}

impl Style {
    pub fn is_empty(&self) -> bool {
        self.fg.is_none() && self.bg.is_none() && self.bold.unwrap_or(false)==false && self.faint.unwrap_or(false)==false && self.italic.unwrap_or(false)==false && self.underline.unwrap_or(false)==false
        // Note: explicit false vs None both mean disabled? For {bold=false}, should be same as empty? Probably. Good.
    }
    pub fn to_ansi_open(&self) -> String {
        if self.is_empty() {
            return String::new();
        }
        let mut parts: Vec<String> = Vec::new();
        if self.bold.unwrap_or(false) { parts.push("1".to_string()); }
        if self.faint.unwrap_or(false) { parts.push("2".to_string()); }
        if self.italic.unwrap_or(false) { parts.push("3".to_string()); }
        if self.underline.unwrap_or(false) { parts.push("4".to_string()); }
        if let Some(bg) = self.bg {
            parts.push(bg.bg_code().to_string());
        }
        if let Some(fg) = self.fg {
            parts.push(fg.fg_code().to_string());
        }
        if parts.is_empty() {
            return String::new();
        }
        format!("\x1b[{}m", parts.join(";"))
    }
    pub fn apply(&self, text: &str, is_keyword_with_bg: bool) -> String {
        if self.is_empty() {
            return text.to_string();
        }
        let open = self.to_ansi_open();
        let close = "\x1b[0m";
        if is_keyword_with_bg && self.bg.is_some() {
            format!("{} {} {}", open, text, close.trim_start_matches('\x1b').to_string())
            // Actually need open + " " + text + " " + close
            // close is \x1b[0m, so format!
        } else {
            // placeholder, will handle correctly below
            format!("{}{}{}", open, text, close)
        }
    }
    pub fn apply_keyword(&self, text: &str) -> String {
        if self.is_empty() {
            return text.to_string();
        }
        let open = self.to_ansi_open();
        let close = "\x1b[0m";
        if self.bg.is_some() {
            format!("{} {} {}", open, text, close)
            // open + " " + text + " " + close? Actually open already includes \x1b[...m, then space, text, space, close
            // So: format!("{} {} {}", open, text, close) gives "open + space + text + space + close"? No, open + " " + text + " " + close? That's "{} {} {}" with open, text, close => "open + space + text + space + close". Good.
        } else {
            format!("{}{}{}", open, text, close)
        }
    }
    pub fn apply_plain(&self, text: &str) -> String {
        if self.is_empty() {
            return text.to_string();
        }
        let open = self.to_ansi_open();
        format!("{}{}\x1b[0m", open, text)
    }
}

