use crate::theme::{Theme, Style, Color};
use regex::Regex;
use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

pub struct Highlighter {
    theme: Theme,
    enabled: HashSet<String>,
    disable_builtin: bool,
    // custom: Vec<(color_style, words)> in order: theme keywords first, then flag highlights
    custom: Vec<(Style, Vec<String>)>,
}

impl Highlighter {
    pub fn new(theme: &Theme, enable: &[String], disable: &[String], disable_builtin: bool, flag_highlights: Vec<(String, Vec<String>)>) -> Self {
        let all = ["numbers","urls","pointers","dates","paths","quotes","key-value-pairs","uuids","ip-addresses","processes","json"];
        let enabled: HashSet<String> = if !enable.is_empty() {
            enable.iter().cloned().collect()
        } else if !disable.is_empty() {
            let dis: HashSet<String> = disable.iter().cloned().collect();
            all.iter().filter(|s| !dis.contains(&***s)).map(|s| s.to_string()).collect()
        } else {
            all.iter().map(|s| s.to_string()).collect()
        };
        // build custom: theme keywords first
        let mut custom: Vec<(Style, Vec<String>)> = Vec::new();
        for kw in &theme.custom_keywords {
            // filter empty words? Keep as is but filter empties to avoid bugs? Keep non-empty only
            let words: Vec<String> = kw.words.iter().filter(|w| !w.is_empty()).cloned().collect();
            if words.is_empty() { continue; }
            custom.push((kw.style.clone(), words));
        }
        for (color_name, words) in flag_highlights {
            let style = color_to_style(&color_name);
            let filtered: Vec<String> = words.into_iter().filter(|w| !w.is_empty()).collect();
            if filtered.is_empty() { continue; }
            custom.push((style, filtered));
        }
        Self { theme: theme.clone(), enabled, disable_builtin, custom }
    }

    fn is_enabled(&self, name: &str) -> bool {
        self.enabled.contains(name)
    }

    pub fn highlight(&self, line: &str) -> String {
        // Fast path: empty line?
        // Apply in order
        let mut s = line.to_string();
        // 1. json (if enabled and line is JSON)
        if self.is_enabled("json") {
            s = highlight_json(&s, &self.theme);
        }
        // 2. dates
        if self.is_enabled("dates") {
            s = highlight_dates(&s, &self.theme);
        }
        // 3. ip
        if self.is_enabled("ip-addresses") {
            s = highlight_ip(&s, &self.theme);
        }
        // 4. uuids
        if self.is_enabled("uuids") {
            s = highlight_uuid(&s, &self.theme);
        }
        // 5. pointers
        if self.is_enabled("pointers") {
            s = highlight_pointers(&s, &self.theme);
        }
        // 6. urls
        if self.is_enabled("urls") {
            s = highlight_urls(&s, &self.theme);
        }
        // 7. paths
        if self.is_enabled("paths") {
            s = highlight_paths(&s, &self.theme);
        }
        // 8. processes
        if self.is_enabled("processes") {
            s = highlight_processes(&s, &self.theme);
        }
        // 9. key-value
        if self.is_enabled("key-value-pairs") {
            s = highlight_kv(&s, &self.theme);
        }
        // 10. numbers
        if self.is_enabled("numbers") {
            s = highlight_numbers(&s, &self.theme);
        }
        // 11. builtin keywords
        if !self.disable_builtin {
            s = highlight_builtins(&s);
        }
        // 12. custom
        s = highlight_custom(&s, &self.custom);
        // 13. quotes
        if self.is_enabled("quotes") {
            s = highlight_quotes(&s, &self.theme);
        }
        s
    }
}

fn color_to_style(name: &str) -> Style {
    let c = match name.to_lowercase().as_str() {
        "red" => Color::Red,
        "green" => Color::Green,
        "yellow" => Color::Yellow,
        "blue" => Color::Blue,
        "magenta" => Color::Magenta,
        "cyan" => Color::Cyan,
        _ => Color::Red,
    };
    Style { fg: Some(c), ..Default::default() }
}

// Helper: check if match contains ANSI (already highlighted inside) -> skip
fn contains_ansi(s: &str) -> bool {
    s.contains('\x1b')
}

// Helper: apply style to match, skipping if contains ANSI
fn apply_if_no_ansi(text: &str, style: &Style, is_keyword: bool) -> String {
    if style.is_empty() {
        return text.to_string();
    }
    // for quotes empty fix? Handled separately
    if is_keyword {
        style.apply_keyword(text)
    } else {
        style.apply_plain(text)
    }
}

// Numbers
fn highlight_numbers(s: &str, theme: &Theme) -> String {
    static RE: OnceLock<Regex> = OnceLock::new();
    let re = RE.get_or_init(|| Regex::new(r"\b\d+(?:\.\d+)?\b").unwrap());
    let style = &theme.numbers_number;
    if style.is_empty() { return s.to_string(); }
    let open = style.to_ansi_open();
    // replace with open + match + close, but skip matches containing ANSI? Since numbers regex won't match across ANSI due to \b, but check anyway
    re.replace_all(s, |caps: &regex::Captures| {
        let m = caps.get(0).unwrap().as_str();
        if contains_ansi(m) { return m.to_string(); }
        format!("{}{}\x1b[0m", open, m)
    }).to_string()
}

// URLs
fn highlight_urls(s: &str, theme: &Theme) -> String {
    // Find https?://\S+ then parse
    static RE: OnceLock<Regex> = OnceLock::new();
    let re = RE.get_or_init(|| Regex::new(r"https?://[^\s]+").unwrap());
    re.replace_all(s, |caps: &regex::Captures| {
        let m = caps.get(0).unwrap().as_str();
        if contains_ansi(m) { return m.to_string(); }
        // Trim trailing punctuation except '.' '/'? Actually trim ,;!?\)\]}"' + :? Keep '.'?
        // For now, trim trailing ,;!?\)\]}"' (excluding '.' and '/' and ':'? But ':' trailing should be trimmed as well? Let's trim ,;!?\)\]}"' plus ':'? Keep '.'?
        let mut url = m.to_string();
