        if self.is_enabled("dates") { s = highlight_dates(&s, &self.theme); }
        if self.is_enabled("ip-addresses") { s = highlight_ip(&s, &self.theme); }
        if self.is_enabled("uuids") { s = highlight_uuid(&s, &self.theme); }
        if self.is_enabled("pointers") { s = highlight_pointers(&s, &self.theme); }
        if self.is_enabled("urls") { s = highlight_urls(&s, &self.theme); }
        if self.is_enabled("paths") { s = highlight_paths(&s, &self.theme); }
        if self.is_enabled("processes") { s = highlight_processes(&s, &self.theme); }
        if self.is_enabled("key-value-pairs") { s = highlight_kv(&s, &self.theme); }
