    static RE6: OnceLock<Regex> = OnceLock::new();
    let re6 = RE6.get_or_init(|| Regex::new(r"\b(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}\b").unwrap());
