fn valid_01_31(s: &str) -> bool {
    if s.len() != 2 { return false; }
    if !s.chars().all(|c| c.is_ascii_digit()) { return false; }
    let v: u32 = s.parse().unwrap_or(0);
    v >= 1 && v <= 31
}
fn valid_hour(s: &str) -> bool {
    if s.is_empty() || s.len() > 2 { return false; }
    if !s.chars().all(|c| c.is_ascii_digit()) { return false; }
    if s.len() == 1 { return true; } // single digit 0-9? What about single "0"? Probably valid. Good.
    let v: u32 = s.parse().unwrap_or(99);
    v <= 23
}
fn valid_00_59(s: &str) -> bool {
    if s.len() != 2 { return false; }
    if !s.chars().all(|c| c.is_ascii_digit()) { return false; }
