fn highlight_urls(s: &str, theme: &Theme) -> String {
    static RE: OnceLock<Regex> = OnceLock::new();
    let re = RE.get_or_init(|| Regex::new(r"https?://[^\s]+").unwrap());
    re.replace_all(s, |caps: &regex::Captures| {
        let m = caps.get(0).unwrap().as_str();
        if contains_ansi(m) { return m.to_string(); }
        let mut url = m.to_string();
        let mut suffix = String::new();
        loop {
            let c = match url.chars().last() { Some(c) => c, None => break };
            if c == ',' || c == ';' || c == '!' || c == ')' || c == ']' || c == '}' || c == '"' || c == '\'' || c == ':' || c == '?' {
                // For '?' need to ensure not part of query? If url is "https://example.com?" (ends with ? with no query), trim. If "https://example.com/a?b=c" ends with "c", not trimmed. Good.
                // But what about "https://example.com/path?" (ends with ? after path, no query)? Trim. Good.
                // For "https://example.com/a?b=c?" trailing "?" after query value? Trim as well (edge).
                suffix.insert(0, c);
                url.pop();
            } else { break; }
        }
        let highlighted = highlight_url_parts(&url, theme);
        format!("{}{}", highlighted, suffix)
    }).to_string()
}
fn highlight_url_parts(url: &str, theme: &Theme) -> String {
    let pos = match url.find("://") { Some(p) => p, None => return url.to_string() };
    let scheme = &url[..pos];
    let rest = &url[pos+3..];
    if scheme != "http" && scheme != "https" { return url.to_string(); }
    let scheme_styled = if scheme == "http" {
        if theme.urls_http.is_empty() { scheme.to_string() } else { format!("{}{}\x1b[0m", theme.urls_http.to_ansi_open(), scheme) }
    } else {
        if theme.urls_https.is_empty() { scheme.to_string() } else { format!("{}{}\x1b[0m", theme.urls_https.to_ansi_open(), scheme) }
    };
    let mut host_end = rest.len();
    for (i, c) in rest.char_indices() {
        if c == '/' || c == '?' || c == '#' || c == ':' { host_end = i; break; }
    }
    let host = &rest[..host_end];
    let mut remaining = &rest[host_end..];
    if host.is_empty() { return format!("{}://{}", scheme_styled, remaining); }
    let host_styled = if theme.urls_host.is_empty() { host.to_string() } else { format!("{}{}\x1b[0m", theme.urls_host.to_ansi_open(), host) };
    let mut out = format!("{}://{}", scheme_styled, host_styled);
    if remaining.starts_with(':') {
        let mut pe = remaining.len();
        for (i, c) in remaining.char_indices().skip(1) {
            if c == '/' || c == '?' || c == '#' { pe = i; break; }
        }
        out.push_str(&remaining[..pe]);
        remaining = &remaining[pe..];
    }
    if remaining.starts_with('/') {
        let mut pe = remaining.len();
        for (i, c) in remaining.char_indices() {
            if c == '?' || c == '#' { pe = i; break; }
        }
        let path = &remaining[..pe];
        if theme.urls_path.is_empty() { out.push_str(path); } else { out.push_str(&format!("{}{}\x1b[0m", theme.urls_path.to_ansi_open(), path)); }
        remaining = &remaining[pe..];
    } else {
        if remaining.is_empty() || remaining.starts_with('?') || remaining.starts_with('#') {
            if !theme.urls_path.is_empty() { out.push_str(&format!("{}\x1b[0m", theme.urls_path.to_ansi_open())); }
        }
    }
    if remaining.starts_with('?') {
        let mut qe = remaining.len();
        for (i, c) in remaining.char_indices() {
            if c == '#' { qe = i; break; }
        }
        let query = &remaining[..qe];
        out.push_str("\x1b[31m?\x1b[0m");
        let qs = &query[1..];
        let parts: Vec<&str> = qs.split('&').collect();
        for (idx, part) in parts.iter().enumerate() {
            if idx > 0 { out.push_str("\x1b[31m&\x1b[0m"); }
            if let Some(eq) = part.find('=') {
                let k = &part[..eq]; let v = &part[eq+1..];
                if theme.urls_qkey.is_empty() { out.push_str(k); } else { out.push_str(&format!("{}{}\x1b[0m", theme.urls_qkey.to_ansi_open(), k)); }
                out.push_str("\x1b[31m=\x1b[0m");
                if theme.urls_qval.is_empty() { out.push_str(v); } else { out.push_str(&format!("{}{}\x1b[0m", theme.urls_qval.to_ansi_open(), v)); }
            } else {
                if theme.urls_qkey.is_empty() { out.push_str(part); } else { out.push_str(&format!("{}{}\x1b[0m", theme.urls_qkey.to_ansi_open(), part)); }
            }
        }
        remaining = &remaining[qe..];
    }
    if !remaining.is_empty() { out.push_str(remaining); }
    out
}
fn apply_hex_char(c: char, theme: &Theme, is_pointer: bool) -> String {
    if c.is_ascii_digit() {
        let style = if is_pointer { &theme.pointers_number } else { &theme.uuid_number };
        if style.is_empty() { c.to_string() } else { format!("{}{}\x1b[0m", style.to_ansi_open(), c) }
    } else {
        let style = if is_pointer { &theme.pointers_letter } else { &theme.uuid_letter };
        if style.is_empty() { c.to_string() } else { format!("{}{}\x1b[0m", style.to_ansi_open(), c) }
    }
}
fn highlight_pointers(s: &str, theme: &Theme) -> String {
